import { writeFileSync, readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const srcDir = join(process.cwd(), 'src');
const primitivesDir = join(srcDir, 'primitives');

const files = readdirSync(primitivesDir).filter(f => f.endsWith('.vx'));

let indexContent = `/**
 * VX Compiler - Primitive Widget Registry
 * 
 * This file is automatically generated. It exports the names and raw source
 * definitions of all native primitives known to the VX compiler.
 */

export const PRIMITIVE_NAMES = [
`;

for (const file of files) {
  const name = file.replace('.vx', '');
  indexContent += `  '${name}',\n`;
}

indexContent += `];\n\n`;

indexContent += `export const PRIMITIVE_SOURCES: Record<string, string> = {\n`;

for (const file of files) {
  const name = file.replace('.vx', '');
  const content = readFileSync(join(primitivesDir, file), 'utf-8');
  indexContent += `  '${name}': \`${content.replace(/`/g, '\\`').replace(/\\$/g, '\\\\$')}\`,\n`;
}

indexContent += `};\n`;

writeFileSync(join(srcDir, 'index.ts'), indexContent);

console.log(`Successfully indexed ${files.length} primitive .vx files into src/index.ts registry.`);
